/**
 * @brief Possible results returned for mode requests.
 */
typedef enum {
    /**  Unknown result. */
    MAVSDK_MODES_RESULT_UNKNOWN = 0,
    /**  Request was successful. */
    MAVSDK_MODES_RESULT_SUCCESS = 1,
    /**  No system is connected. */
    MAVSDK_MODES_RESULT_NO_SYSTEM = 2,
    /**  Connection error. */
    MAVSDK_MODES_RESULT_CONNECTION_ERROR = 3,
    /**  Vehicle is busy. */
    MAVSDK_MODES_RESULT_BUSY = 4,
    /**  Request was denied, e.g. because the mode can't be entered right now. */
    MAVSDK_MODES_RESULT_DENIED = 5,
    /**  Mode or command is not supported. */
    MAVSDK_MODES_RESULT_UNSUPPORTED = 6,
    /**  Request timed out. */
    MAVSDK_MODES_RESULT_TIMEOUT = 7,
    /**  Request failed. */
    MAVSDK_MODES_RESULT_FAILED = 8,
    /**  No available mode with this name. */
    MAVSDK_MODES_RESULT_MODE_NOT_FOUND = 9,
    /**  The available modes have not been received yet. */
    MAVSDK_MODES_RESULT_MODES_NOT_KNOWN_YET = 10,
} mavsdk_modes_result_t;



